export const dateIsValid = (value: string) => !Number.isNaN(new Date(value).getTime());

export const formatedDate = (value: string, formatOptions?: Intl.DateTimeFormatOptions) => {
  const date = new Intl.DateTimeFormat('en-US', formatOptions).format(
    dateIsValid(value) ? new Date(value) : undefined
  );
  return date;
};
